        },
        {
          "name": "address_type",
          "comment": "类型(shipping/billing)",
          "constraint": ""
        },
        {
          "name": "recipient_first_name",
          "comment": "收件人名",
          "constraint": ""
        },
        {
          "name": "recipient_last_name",
          "comment": "收件人姓",
          "constraint": ""
        },
        {
          "name": "recipient_name",
          "comment": "完整姓名(冗余拼接)",
          "constraint": ""
        },
        {
          "name": "phone_country",
          "comment": "电话区号(+1)",
          "constraint": ""
