        {
          "name": "phone_number",
          "comment": "电话号码",
          "constraint": ""
        },
        {
          "name": "alternate_phone_country",
          "comment": "备用电话区号(中东预留)",
          "constraint": ""
        },
        {
          "name": "alternate_phone_number",
          "comment": "备用电话号码(中东预留)",
          "constraint": ""
        },
        {
          "name": "address_line1",
          "comment": "地址行1(街道)",
          "constraint": ""
