          "comment": "Google Place ID",
          "constraint": "UNIQUE"
        },
        {
          "name": "latitude",
          "comment": "纬度",
          "constraint": ""
        },
        {
          "name": "longitude",
          "comment": "经度",
          "constraint": ""
        },
        {
          "name": "verified",
          "comment": "是否已验证(V1.1预留)",
          "constraint": ""
        },
        {
          "name": "verified_at",
          "comment": "验证时间",
          "constraint": ""
        },
        {
          "name": "verified_source",
          "comment": "验证来源(google/usps/loqate)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "核心实体，超集字段设计支持多国扩展"
    },
    {
      "name": "delivery_restriction",
      "comment": "配送限制规则",
