          "name": "id",
          "comment": "主键 UUID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "merchant_id",
          "comment": "商家ID(NULL=自营规则)",
          "constraint": "FOREIGN KEY"
        },
        {
