        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "restriction_type",
          "comment": "类型(fixed/custom)",
          "constraint": ""
        },
        {
          "name": "category",
          "comment": "适用品类(当前固定全品类)",
          "constraint": ""
        },
        {
          "name": "match_field",
          "comment": "匹配字段(address_line1/city/state等)",
          "constraint": ""
        },
        {
          "name": "match_method",
          "comment": "匹配方式(keyword/regex/state_select)",
          "constraint": ""
        },
        {
          "name": "match_pattern",
          "comment": "匹配内容(关键词或正则)",
          "constraint": ""
        },
        {
          "name": "match_states",
          "comment": "限制州列表(JSON,州选择时使用)",
          "constraint": ""
        },
        {
          "name": "error_message_i18n_key",
          "comment": "i18n Key(系统自动设置，不可编辑)",
          "constraint": ""
        },
        {
          "name": "remark",
          "comment": "规则备注说明",
          "constraint": ""
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "平台自营(merchant_id=NULL)或商家规则，各自独立管理互不影响"
