    {
      "name": "address_field_meta",
      "comment": "地址字段元数据",
      "columns": [
        {
          "name": "id",
          "comment": "主键 UUID",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "field_name",
          "comment": "字段标识(=address表列名)",
          "constraint": "UNIQUE"
        },
        {
          "name": "field_type",
          "comment": "字段类型(text/select/phone)",
          "constraint": ""
        },
        {
          "name": "category",
          "comment": "分类(recipient/address/geo)",
          "constraint": ""
        },
        {
          "name": "display_name",
          "comment": "后台展示名",
          "constraint": ""
        },
        {
          "name": "admin_division_level",
          "comment": "关联行政区划层级(NULL=不关联)",
          "constraint": ""
        },
        {
          "name": "max_length",
          "comment": "数据库列最大长度",
          "constraint": ""
        },
        {
          "name": "description",
          "comment": "后台说明(给运营)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
