          "comment": "国家代码(引用market)",
          "constraint": "FOREIGN KEY, UNIQUE"
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        },
        {
          "name": "field_config",
          "comment": "字段配置(JSON: enabled)",
          "constraint": ""
        },
        {
          "name": "field_order",
          "comment": "字段顺序(JSON)",
          "constraint": ""
        },
        {
          "name": "field_i18n_keys",
          "comment": "字段国际化文案Key(JSON)",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
