          "constraint": ""
        },
        {
          "name": "priority",
          "comment": "执行优先级(值小先执行)",
          "constraint": ""
        },
        {
          "name": "pattern",
          "comment": "正则表达式(pattern/custom时使用)",
          "constraint": ""
        },
        {
          "name": "min_length",
          "comment": "最小长度(length时使用)",
          "constraint": ""
        },
        {
          "name": "max_length",
          "comment": "最大长度(length时使用)",
          "constraint": ""
        },
        {
          "name": "execute_on",
          "comment": "执行端(client/server/both)",
          "constraint": ""
        },
        {
          "name": "severity",
          "comment": "严重程度(error/warning)",
          "constraint": ""
        },
        {
          "name": "required_level",
          "comment": "必填性(required/optional/conditional)",
          "constraint": ""
        },
        {
          "name": "error_message_i18n_key",
          "comment": "多语言key",
          "constraint": ""
        },
        {
          "name": "enabled",
          "comment": "是否启用",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
