        },
        {
          "name": "sort_order",
          "comment": "排序权重",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "各国行政区划树形数据(州/市/区)，支撑下拉选择"
    },
    {
