        },
        {
          "name": "country_code",
          "comment": "国家代码",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "postal_code",
          "comment": "邮政编码",
          "constraint": "UNIQUE"
        },
        {
          "name": "city",
          "comment": "城市",
          "constraint": ""
        },
        {
          "name": "state_code",
          "comment": "州/省代码",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
