    }
  ],
  "relations": [
    {
      "from": "user",
      "to": "address",
      "type": "1:N",
      "label": "拥有多个地址",
      "color": "#1565C0",
      "penwidth": 1.8
    },
    {
      "from": "country",
      "to": "address",
      "type": "1:N",
      "label": "地址所属国家",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "country_address_config",
      "type": "1:1",
      "label": "国家字段配置",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "address_field_validation_rules",
      "type": "1:N",
      "label": "校验规则(按国家)",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "postal_code_mapping",
      "type": "1:N",
      "label": "邮编数据",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "administrative_division",
      "type": "1:N",
      "label": "行政区划数据",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "administrative_division",
      "to": "administrative_division",
      "type": "1:N",
      "label": "父子层级(自引用)",
      "color": "#E8833A",
      "penwidth": 1.2,
      "style": "dashed"
    },
    {
      "from": "address_field_meta",
      "to": "country_address_config",
      "type": "1:N",
      "label": "field_config引用字段元数据",
      "color": "#2E7D32",
      "penwidth": 1.4,
      "style": "dashed"
    },
    {
      "from": "address_field_meta",
      "to": "address_field_validation_rules",
      "type": "1:N",
      "label": "field_name引用元数据",
      "color": "#2E7D32",
      "penwidth": 1.4
    },
    {
      "from": "merchant",
      "to": "delivery_restriction",
      "type": "1:N",
      "label": "商家配送限制",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "country",
      "to": "delivery_restriction",
      "type": "1:N",
      "label": "国家配送限制",
      "color": "#7B1FA2",
      "penwidth": 1.4
    },
    {
      "from": "address_field_meta",
      "to": "administrative_division",
      "type": "1:N",
      "label": "admin_division_level映射",
      "color": "#2E7D32",
      "penwidth": 1.2,
      "style": "dashed"
    }
  ],
  "design_rules": {
    "superset_fields": "超集字段设计：数据库包含所有国家字段，通过country_address_config控制展示",
    "field_registry": "address_field_meta是字段的单一事实来源",
    "admin_division_mapping": "admin_division_level数据驱动行政区划映射：state_province→L1, city→L2, district→L3",
    "market_integration": "国家可用性引用market模块，地址库不独立维护国家列表",
    "frontend_i18n": "前端多语言采用i18n方案，数据库不存储多语言字段",
    "name_split": "recipient_first_name + recipient_last_name 拆分存储，支持支付AVS和物流API",
    "name_concat": "recipient_name 冗余存储拼接结果",
    "soft_delete": "地址数据支持软删除(CCPA要求可彻底删除)",
    "encryption": "phone_number, recipient_first_name, recipient_last_name 字段 AES-256 加密存储",
    "place_id_dedup": "通过 place_id 做地址去重(V1.1)",
    "mvp_scope": "MVP只启用美国(US)",
    "merchant_isolation": "配送限制多商家隔离：merchant_id=NULL为自营规则，有值为商家规则，各自独立互不影响",
    "fixed_rule_immutable": "固定规则(restriction_type=fixed): PO Box/军事地址，系统初始化不可修改识别逻辑，仅可toggle启用/禁用",
    "fixed_rule_i18n": "固定规则i18n key固定且系统自动设置：delivery_restriction.po_box / delivery_restriction.military，后台不提供编辑入口",
    "custom_rule_i18n": "自定义规则统一i18n key：delivery_restriction.general，系统自动设置，文案固定\"该地址不支持配送\"，后台不提供编辑入口",
    "i18n_key_system_managed": "所有配送限制规则的error_message_i18n_key由系统根据规则类型自动写入，后台管理界面不暴露该字段",
    "no_scope_no_inheritance": "无适用范围概念：平台管自营、商家管自己，互不干涉、不存在继承或强制关系",
    "delivery_check_logic": "地址校验时：自营订单检查merchant_id=NULL的规则；商家订单检查该merchant_id的规则+固定规则",
    "category_future": "category字段预留品类维度限制能力，MVP阶段固定为全品类(all)",
    "public_data_ownership": "公共数据(国家地址配置/行政区划/邮编)由超级管理员维护，不区分商家"
  }
}
